    "あの日、降ろされた私が……今、あそこの選手に勝ちましたっ……!": "The day they pulled me from the card... and now I've beaten one of theirs...!",
    "あの瞬間、何が刺さるか見えた": "In that moment I saw what would land.",
    "あはは…痛い痛い…でもね！": "Ahaha... ow, ow... but hey!",
