    "あはは、なんか面白そうだね。よろしく～": "Ahaha, this looks like fun. Good to be here~",
    "あはは、勝っちゃったね。どうも、どうも": "Ahaha, look at that, I won. Thanks, thanks.",
    "あはは！ パワーで押し切っちゃった！ テクニック？ 何それ♪": "Ahaha! Just muscled straight through! Technique? What's that ♪",
    "あまり私を舐めない事ね…": "You would do well not to take me lightly...",
    "あら…もう終わり？ もっと苦しんでくれると思ったのに♡": "Oh... over already? I thought you would suffer a little longer for me ♡",
    "あら…乱暴ね…でも嫌いじゃないわ": "Oh my... how rough... though I don't mind it.",
    "あら…動けないわ…": "Oh dear... I can't move...",
    "あら、お金じゃない形ですの？ まあ、それも素敵ですわね。": "Oh? Not in money, then? Well, that is rather lovely as well.",
    "あら、お金の話そらされた〜。でもまあ、ありがと社長。": "Oh my, the money question slipped right past~. Thanks anyway, Boss.",
