    "あら、そんな話してましたの？ 注意しておきますわ〜。": "Oh, they were saying such things? I shall see to it~.",
    "あら、つれないですこと。まあいいですわ〜。": "Oh, how unkind of you. Never mind, then~.",
    "あら、ばれちゃった？ 明日から出るね〜。": "Oh my, caught out? I'll be there from tomorrow~.",
    "あら、ばれてましたの？ 明日から出ますわ〜。": "Oh, was I found out? I shall attend from tomorrow~.",
    "あら、もう終わり？ ……身の程を知るには、ちょうどよい薬でしたわね": "My. Over already? ...A fitting dose of medicine for learning one's place.",
    "あら、もう落ちたの? 物足りないわね": "Oh my. Out already? How unsatisfying.",
    "あら、わたくしより皆優先ですの？ ありがたいですわ〜。": "Oh, they come before me? How very welcome~.",
