    "あら、メンバー優先？ まあ、助かります〜。": "Oh my, the members first? Well, it helps~.",
    "あら、別の形ですの？ まあ、ありがたいですわ〜。": "Oh? By another road, then? Well, I am grateful all the same~.",
    "あら、別の形？ まあ、ありがとうございます〜。": "Oh my, another form? Well then — thank you~.",
    "あら、別の手立てですの？ ありがたいですわ〜。": "Oh, by other means, then? How very welcome~.",
