    "あらあら…動けませんわ…": "Oh my, oh my... I cannot move...",
    "あらあら、うまくいきましたわね": "My, my. That did go rather well, did it not?",
    "あらあら。体調が悪かったのかしら？ごめんなさいね": "Well, well. Weren't you feeling your best? So sorry about that.",
    "あらあら。情けなく伸びたその顔♪無様ねぇ♪": "Well, well. That pitiful stretched-out face ♪ How unbecoming ♪",
