    "あらら、見られてました〜？ じゃ、控えますね。": "Oh dear, that was noticed~? Then I'll hold back.",
    "あらら、見られてましたか。明日から、ちゃんとしますね。": "Oh dear, you saw. I'll straighten up from tomorrow.",
    "あらら、見られてましたか〜。気をつけますね。": "Oh dear, that got noticed~. I'll mind it.",
    "あらら、見られてました？ じゃ、緩めますね〜。": "Oh dear, you'd seen? Then I'll ease off~.",
    "あらら、負けてしまいましたわ…でも次は頑張りますの、{partner}さん。": "Oh dear, we have lost... but I shall be better next time, {partner}.",
    "あらら、配慮足りませんでしたね〜。気をつけます。": "Oh dear, that was thoughtless of us~. I'll mind it.",
    "あら？勝った？ちょっと弱すぎない？": "Hm? I won? Weren't you a bit too easy?",
    "ありがたく頂いておくよ。期待はきっちり超えてみせるから、見てて。": "I'll take that, thank you. We'll go past whatever you're expecting. Watch.",
    "ありがとう、社長。期待してて、ちゃんと魅せるから。": "Thank you, Boss. Expect something — I'll make it worth watching.",
