    "ありがとうござ〜っす。": "Thanks a bu-unch~.",
    "ありがとうございま〜す、楽しんでこまーす。": "Thank you so mu-uch~, we'll go have fun~.",
    "ありがとうございま〜す。": "Thank you so mu-uch~.",
    "ありがとうございます……！また応援してください": "Thank you so much...! Please keep cheering for me.",
    "ありがとうございます…社長、その一言、ずっと欲しかったです。": "Thank you... Boss, I've wanted to hear that for a long time.",
    "ありがとうございます…社長、その言葉、染みます。": "Thank you... Boss, that one goes right in.",
    "ありがとうございます。": "Thank you.",
    "ありがとうございます。お任せいただいた以上、結果で示します。": "Thank you. You've trusted us with it, so we'll show you in results.",
    "ありがとうございます。お言葉、しっかり受け取ります。": "Thank you. I'll take those words and keep them.",
    "ありがとうございます。お預かりした以上、形にしてお返しします。": "Thank you. It's ours to hold now, and we'll hand it back in one piece.",
    "ありがとうございます。その言葉、励みにします。": "Thank you. I'll run on that for a while.",
    "ありがとうございます。その言葉、胸に留めます。": "Thank you. That stays with me.",
    "ありがとうございます。まだまだ積み上げていきます": "Thank you. I've got a lot more to build on.",
    "ありがとうございます。みんなにも伝えます。": "Thank you. I'll tell the others.",
    "ありがとうございます。みんな喜びます。": "Thank you. They'll be glad.",
    "ありがとうございます。やりますね。": "Thank you. We'll handle it.",
    "ありがとうございます。任された以上、応えます。": "Thank you. It's ours now. We'll answer for it.",
    "ありがとうございます。休みますね。": "Thank you. I'll take the break.",
    "ありがとうございます。助かります。": "Thank you. That helps.",
    "ありがとうございます。励みにします。": "Thank you. I'll use that.",
    "ありがとうございます。嬉しいです。": "Thank you. That's good to hear.",
    "ありがとうございます。客、ぶち上げてみせますよ。": "Thanks, Boss. We'll blow the roof off that place.",
    "ありがとうございます。期待に応えます。": "Thank you. We'll live up to it.",
    "ありがとうございます。社長…これ、忘れません。": "Thank you. Boss... I won't forget this.",
    "ありがとうございます。私たちも、もっと社長に応えたいと思います。": "Thank you. It makes us want to give you more in return.",
    "ありがとうございます。結果で返します。": "Thank you. Results will follow.",
    "ありがとうございます。続けます。": "Thank you. We'll continue.",
    "ありがとうございます〜、引き続きやらせていただきます。": "Thank you~. I'll go right on with it.",
    "ありがとうございます〜、楽しんできますね。": "Thank you~, we'll go make a night of it.",
    "ありがとうございます〜。": "Thank you~.",
