    "ありがとうございます〜。楽しんできますね。": "Thank you~. We'll go enjoy ourselves.",
    "ありがとうございます〜。社長にそう言ってもらえると、嬉しいです。": "Thank you~. Coming from you, that's a nice thing to hold.",
