    "ありがとうございます〜！ 楽しんできます〜。": "Thank you so much~! We'll go and enjoy it~.",
    "ありがとうございますわ〜、楽しんで参りますわ。": "Thank you~. We shall go and enjoy ourselves.",
    "ありがとうございますわ〜。": "I do thank you~.",
    "ありがとうございますわ〜。穏便に、ですわね。": "Thank you~. Quietly does it, then.",
    "ありがとうございます社長。その一言で十分っすよ。": "Thanks, Boss. One line like that does the job.",
