    "あれ、私じゃなくて子たち優先？ まあ、ありがたいですけど〜。": "Huh, the girls before me? Well, I'll take it~.",
    "あんたたち相手に、ここで膝はつかない。": "Not against you. I'm not going down on one knee here.",
    "あんたら相手に、ここで沈むかよ。": "Like I'm going down here. Against you lot.",
    "あんなに吠えていたのに。……ふふ、床の上だとずいぶん静かなのね": "All that barking earlier. ...Mm. You're very quiet down on the mat.",
    "あー、はい、注意します〜。": "Ahh, right, I'll watch it~.",
    "あー、はい〜、気をつけまーす。": "Ahh, yeah~, I'll watch it~.",
