    "い、行ってくる…わ…": "I-I'm going in... now...",
    "い、行ってまいりますわ…！": "I-I am going in...!",
    "いい女は、リングでも手を抜かないの♡": "A hot girl never slacks off — not even in the ring ♡",
    "いい試合だったね♪ …あ、本音？ もっとやれたんじゃない？": "Good match ♪ ...Oh, honestly? You had more in you than that.",
    "いい試合だったわ。また一つ経験になった……": "That was a good match. Another one to grow from...",
    "いい試合だった！ また戦おうね！": "That was a great match! Let's do it again sometime!",
    "いい試合でした。……またやりたいです、この人とは": "That was a good match. ...I want another one with her.",
    "いい試合でしたっ！ありがとうございました！": "That was a great match! Thank you so much!",
    "いきますよ、二人で！": "Here we go, both of us!",
