    "うっし！ パワーで潰せば何とかなるもんだ！": "Yes! Turns out flattening people works just fine!",
    "うふふ…やりますわね…でも平気ですわ！": "Hehe... you are good... but I am perfectly fine!",
    "うわ、効きます…でも、ここで沈むのは違うんですよね。": "Whoa, that lands... but going down here wouldn't be right.",
    "うわ、効く…でも、ここで沈むのは違うんだよね。": "Whoa, that stings... but going down here? Nah. Not it.",
