    "え…私が勝ったの？ 運動苦手なのに…！": "Huh... I won? But I'm bad at sports...!",
    "え、そんなに気にしてました？ ごめんなさ〜い、次は誘いますって。": "Huh, it bothered them that much? So-orry~, I'll invite them next time.",
    "え、争奪戦ですか！？嬉しいです、頑張ります！": "Wait, a bidding war!? I'm so pleased — I'll work hard!",
    "え、取り合いになってたの？ やったー！ 頑張るね～": "Wait, people were fighting over me? Yesss! I'll make that worth it~",
    "え、気にされてました〜？ ごめんなさい、次は誘いますね〜。": "Oh, it was bothering them~? Sorry, I'll invite them next time~.",
    "え、気にしてました？ ごめんなさ〜い、次は誘いますんで〜。": "Huh, it got to them? So-orry~, we'll bring them next time~.",
    "え、調子いい日だっただけ？ …まぁいいけど♪": "Huh? Just having a good day, you're saying? ...Eh, fine by me ♪",
    "えぇ〜、お客さんノッてたじゃないですか〜。…はい、控えます〜。": "Ohh~, but the crowd was riding it~. ...All right, I'll hold back~.",
    "えぇ〜、お客さんノッてたのに〜。はい、控えますね。": "Ohh~, and the crowd was loving it~. Fine, I'll hold back.",
    "えぇ〜、これくらいいけるんすけどな〜。はい、緩めまっす。": "Ohh~, we can take this much though~. Fine, easing off.",
    "えぇ〜、これくらい大丈夫だと思ったんですけど〜。緩めますね〜。": "Ohh~, I thought this much was fine~. I'll ease off, then~.",
    "えぇ〜、これくらい大丈夫なんですけどぉ。…はぁい、緩めま〜す。": "Ohh~, this much is nothing, though. ...Fi-ine, I'll ease up~.",
