    "えぇ〜、そうですか〜。承知しました。": "Ohh~, is that so~. Understood.",
    "えぇ〜、そんな話あったんですか〜。注意しときます〜。": "Ohh~, was that going around~? I'll keep watch on it~.",
    "えぇ〜、つれない。まあいいですけど〜。": "Aww~, so cold. Fine by me, though~.",
    "えぇ〜、つれない〜。まあいいですけど〜。": "Aww~, so cold of you~. Never mind~.",
    "えぇ〜、つれない〜。まあ次に期待してます。": "Aww~, cold~. I'll keep my hopes on next time.",
    "えぇ〜、つれないっすね〜。まあいいっすけど。": "Aww~, that's cold~. Whatever, it's fine.",
    "えぇ〜、つれないっすね〜。まあいいっすけど〜。": "Aww~, that's cold of you~. Whatever, it's fine~.",
    "えぇ〜、つれないなぁ〜。まあいいですけど。": "Aww~, that's cold~. It's fine, whatever.",
    "えぇ〜、まあ、わかりましたけど〜。": "Aww~. Well. All right, I guess~.",
    "えぇ〜、まあ仕方ないですよね〜。次に期待してます〜。": "Aww~, well, that's how it goes~. Hoping for next time~.",
    "えぇ〜、ケチっすね〜。まあ次に期待してますんで〜。": "Aww~, that's tight-fisted~. Fine, I'll hope for next time~.",
    "えぇ〜、客もノッてたじゃないですか〜。…はーい、控えまーす。": "Ohh~, the crowd was into it, though~. ...Fi-ine, I'll rein it in~.",
    "えぇ〜、客ノッてたじゃないっすか〜。はい、控えまっす。": "Ohh~, the crowd was eating it up though~. Fine, holding back.",
    "えっ、ホントに上げてくれるんですか？ やった〜！ みんなに自慢しちゃう。": "Wait, you're actually raising it? Yesss! I'm telling everybody.",
    "えっホントに〜？ 社長ありがとう！ みんなに自慢しちゃう。": "Wait, really~? Thank you, Boss! I'm going to brag about this.",
    "えへ、バレてました〜？ じゃお言葉に甘えて休みまっす。": "Heh, was it obvious~? Then I'll take you up on it and rest.",
    "えへへ、バレてた？ じゃ、お言葉に甘えて休みまーす。": "Ehehe, was it that obvious? Then I'll take you up on it and rest~.",
    "えー、そんな話してた？ まあ、注意しとくね〜。": "Huh, were they saying that? Well, I'll keep an eye out~.",
