    "お、続けていいんですね〜！ やった〜。": "Oh, we get to keep going~! Nice.",
    "お、見逃してくれるんですか〜？ 助かります〜。": "Oh, you're letting it slide~? That's a relief~.",
    "お〜、放っといてくれるんすか〜。ありがたいっす〜。": "Ohh, you're leaving it alone~? Nice one~.",
