    "お〜、続けていいの？ やった〜！": "Ohh, we can keep going? Lovely!",
    "お〜、続けていいんすか〜！ やった〜！": "Ohh, we get to keep going~! Nice one!",
    "お〜、見逃してくれるの？ 社長優しい〜。": "Ohh, you're letting it go? Kind of you~.",
    "おう、よろしくな。で、いつから暴れていいんだ？": "Yeah, good to be here. So when do I get to cut loose?",
    "おしとやかに見える？ …リングの上では別よ。": "Do I look demure? ...In the ring, that's another matter.",
