    "おっとりしてるって言われるけど…やる時はやるんです！": "People call me easygoing... but when it counts, I deliver!",
    "おやりになりましたわね{partner}さん！ 二人揃えば負けませんわ！": "You were magnificent, {partner}! The two of us together do not lose!",
