    "こ、交代…ね…?": "S-Switching... is that all right...?",
    "こ、交代します…っ": "I-I'm coming in... please...",
    "こういう試合、嫌いじゃない。ボロボロになってからが本番だからね": "I don't mind matches like that. It only really starts once you're wrecked.",
    "こうゆうタイプの女には、絶対負けたくないのよね。": "Girls like her are the ones I refuse to lose to.",
