    "ちゃんと勝ったし、土産話が出来るかな？": "Got the win. Something to tell them about back home, right?",
    "ちゃんと結果は出しますよっ。それってエリートの義務だしね♪": "I get results, obviously. Comes with being elite ♪",
    "ちょっと本気出しちまったな。…ひさびさに。": "Ended up getting serious there. ...Been a while.",
