    "てめえ…やるじゃねえか…": "You... not bad at all...",
    "でかいのは正義。押し潰されたいなら何度でも来なよ": "Big is right. Want to get flattened again? Come back any time.",
    "どう？私の力、思い知った？": "Well? Do you get what I'm capable of now?",
    "どんな勝ち方でも勝ちは勝ち。…ごめんなさいね": "A win is a win, however it comes. ...Sorry about that.",
    "どんな相手だって、自分の強みを生かせば勝てるんだよ": "Anyone can be beaten, as long as you play to what you're good at.",
    "なるほど〜、評価は別の形でってことですね。了解です〜。": "Ahh~, credit in a different currency, then. Got it~.",
    "なんか……うまく引き出せた気がします。楽しかったですよ": "I feel like... I drew a lot out of her. That was fun.",
    "なんとか勝利できました。でも油断はせずに次に備えないと……": "I got through it. But no letting up — I need to be ready for the next one...",
