    "ねぇ社長、次のメイン、わたくしたちにお任せいただけませんこと？": "Now, President. The next main event will be entrusted to us, will it not?",
    "ねじ伏せるというのは、ちょっと品が無いかしら。と思いつつも癖になってしまって": "Wrenching someone into submission is hardly ladylike... and yet it has quite become a habit.",
