    "はぁ…はぁ…！勝った！": "Haah... haah...! I won!",
    "はぁ…少し本気を見せてあげる…": "Haah... let me show you a little of what I keep back...",
    "はぁ…痛い…でもまだ足りないわ": "Haah... that hurts... but it isn't nearly enough.",
