    "はっ…はっ…ふぅ。やっぱり最後まであきらめないのが大事なのよね": "Hah... phew. It really does come down to never giving up, right to the end.",
    "はっ…やるじゃん…でもまだだよ！": "Hah... not bad... but I'm not done!",
