    "はっはっは！ パワーで押し潰すのが一番気持ちいいぜ！": "Hahaha! Nothing feels better than flattening someone with pure power!",
    "ははっ。私にビビッて腰が引けてたなあ。それじゃ勝てないね": "Ha. You were scared of me the whole way, backing off. You won't win like that.",
    "はーい、交代〜！": "Okaaay, swapping in~!",
